    adv_gap = batch['advantage_gap']
    weight = batch.get('weight', None)
    margin = float(extra.get('hyperparams', {}).get('margin', 1.0))
    loss_unweighted = ops.exp(-margin * adv_gap) - 1.0
    if weight is not None:
        weighted_loss = loss_unweighted * weight
        weight_sum = weight.sum()
    else:
        weighted_loss = loss_unweighted
        weight_sum = ops.tensor(adv_gap.shape[0], dtype=adv_gap.dtype, device=adv_gap.device)
    eps = 1e-8
    return weighted_loss.sum() / (weight_sum + eps)

