def generated_loss(batch, model_output, extra):
    adv_gap = batch['advantage_gap']
    weight = batch.get('weight', None)
    margin = float(extra.get('hyperparams', {}).get('margin', 1.0))
    norm = ops.sqrt(ops.mean(ops.pow(adv_gap, 2)))
    norm_adv_gap = adv_gap / (norm + 1e-8)
    loss = ops.exp(-margin * norm_adv_gap) - 1.0
    if weight is not None:
        loss = loss * weight
    return ops.mean(loss)

