def generated_loss(batch, model_output, extra):
    adv_gap = batch['advantage_gap']
    weight = batch.get('weight', None)
    epsilon = float(extra.get('hyperparams', {}).get('epsilon', 1e-6))
    adv_clip = ops.clamp(adv_gap, epsilon)
    loss = ops.div(ops.ones_like(adv_clip), adv_clip)
    if weight is not None:
        loss = ops.mul(loss, weight)
    return loss.mean()

